codeExamples.code:
// The root node
document;
// → #document

// First child (the html tag)
document.documentElement;
// → <html>…</html>

// Direct access to common elements
document.head;
document.body;
console.log(document.body.children);

// By ID
let header = document.querySelector("#header");

// By class
let card = document.querySelector(".card");

// By tag
let firstParagraph = document.querySelector("p");

// By attribute
let link = document.querySelector("a[href='https://example.com']");

console.log(header);  // the #header element

// Scoped: search within a specific element
let sidebar = document.querySelector(".sidebar");
let link = sidebar.querySelector("a");  // first <a> inside .sidebar

// All matches
let allCards = document.querySelectorAll(".card");
console.log(allCards.length);  // total number of cards

allCards.forEach((card, i) => {
  console.log(i + ": " + card.textContent);
});

// getElementById — fastest, most specific
let nav = document.getElementById("main-nav");

// getElementsByClassName — returns a LIVE collection
let items = document.getElementsByClassName("item");
console.log(items.length);  // number of .item elements

// getElementsByTagName
let paragraphs = document.getElementsByTagName("p");
console.log(paragraphs.length);

let liveItems = document.getElementsByClassName("item");
let staticItems = document.querySelectorAll(".item");

console.log("Before: " + liveItems.length);    // 3
console.log("Before: " + staticItems.length);  // 3

// Add a new element dynamically
let newItem = document.createElement("li");
newItem.className = "item";
newItem.textContent = "New";
document.querySelector("ul").appendChild(newItem);

console.log("After live: " + liveItems.length);    // 4 (updated!)
console.log("After static: " + staticItems.length);  // 3 (same snapshot)
